<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Common\Application\Usecase\Install;

use Civi\Lughauth\Shared\Value\Random;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Access\TenantTermsOfUse\Domain\Gateway\TenantTermsOfUseWriteGateway;
use Civi\Lughauth\Features\Access\TenantTermsOfUse\Domain\TenantTermsOfUse;
use Civi\Lughauth\Features\Access\TenantTermsOfUse\Domain\TenantTermsOfUseAttributes;

/**
 * Installation step that seeds the initial Terms of Use record for the root tenant.
 *
 * This class is invoked once during the initial system installation by InstallUsecase. It
 * creates a TenantTermsOfUse entity linked to the provided root tenant, populated with the
 * placeholder HTML content from contents/terms-of-use.html, and sets its activation date
 * to the current instant.
 *
 * The record is enabled immediately after creation so it is available for acceptance flows
 * as soon as the installation completes. The HTML content can be replaced via the
 * TenantTermsOfUse management API without re-running the installation.
 */
class InstallTermsOfUse
{
    private const string CONTENT_DIR = __DIR__ . '/contents/';

    public function __construct(
        private readonly TenantTermsOfUseWriteGateway $terms,
    ) {
    }

    /**
     * Creates and enables the initial Terms of Use record for the given tenant
     * using the content from contents/terms-of-use.html.
     */
    public function install(TenantRef $tenant): void
    {
        $text = (string) file_get_contents(self::CONTENT_DIR . 'terms-of-use.html');

        $attrs = new TenantTermsOfUseAttributes();
        $attrs->uid(Random::comb());
        $attrs->tenant($tenant);
        $attrs->text($text);
        $attrs->activationDate(new \DateTimeImmutable());
        $created = $this->terms->create(TenantTermsOfUse::create($attrs));
        $this->terms->update($created, $created->enable());
    }
}
